missing = []
labels = []
for row in doc.labels:
    labels.append(row.label)
is_manual = "Manual" in labels
if not labels:
    missing.append("Labels")
if not is_manual and not doc.ai_tools_feedback:
    missing.append("AI Tools Feedback")
if labels and not is_manual and not doc.execution_prompt_count:
    missing.append("Execution Prompt Count (cannot be 0 for non-Manual work items)")
result["ai_feedback_complete"] = len(missing) == 0
if missing:
    frappe.msgprint("Please add the following before proceeding: " + ", ".join(missing))
